import json
from itertools import permutations

def time_to_minutes(t):
    # t format: 'H:MM' in 24-hour time
    h, m = t.split(':')
    return int(h) * 60 + int(m)

def minutes_to_time(mins):
    h = mins // 60
    m = mins % 60
    return f"{h}:{m:02d}"

def get_travel_time(travel, src, dst):
    if src == dst:
        return 0
    return travel[src][dst]

def evaluate_order(order, start_loc, start_time_min, travel, people_map):
    n = len(order)
    if n == 0:
        return None

    # Build sequence info
    seq = [people_map[name] for name in order]

    # Backward pass to compute latest starts ensuring minimum durations for suffix
    latest_start = [None] * n
    # Last person latest start = availability_end - min_duration
    last = seq[-1]
    latest_start[-1] = last['end_min'] - last['min_duration']

    # If latest start is before availability start, clip to availability start for feasibility check later
    for i in range(n - 2, -1, -1):
        curr = seq[i]
        nxt = seq[i + 1]
        travel_t = get_travel_time(travel, curr['location'], nxt['location'])
        # Latest finish at current to allow next to start by its latest_start
        latest_finish_curr = min(curr['end_min'], latest_start[i + 1] - travel_t)
        latest_start[i] = latest_finish_curr - curr['min_duration']

    # Forward pass to build concrete schedule
    itinerary = []
    current_loc = start_loc
    current_time = start_time_min

    for i, person in enumerate(seq):
        # Travel to person's location
        travel_t = get_travel_time(travel, current_loc, person['location'])
        arrival = current_time + travel_t

        # Start time is max of arrival and availability start
        start = max(arrival, person['start_min'])

        # Determine the max allowable end time
        if i < n - 1:
            # Must leave enough time to get to next and start by latest_start[i+1]
            to_next = get_travel_time(travel, person['location'], seq[i + 1]['location'])
            max_end = min(person['end_min'], latest_start[i + 1] - to_next)
        else:
            max_end = person['end_min']

        # Ensure meeting at least min_duration
        end = max_end
        if end < start + person['min_duration']:
            return None  # infeasible

        itinerary.append({
            "action": "meet",
            "location": person['location'],
            "person": person['name'],
            "start_time": minutes_to_time(start),
            "end_time": minutes_to_time(end),
            "_start_min": start,
            "_end_min": end
        })

        current_loc = person['location']
        current_time = end

    # Validate minimums explicitly and windows
    for i, person in enumerate(seq):
        meet = itinerary[i]
        dur = meet["_end_min"] - meet["_start_min"]
        if dur < person['min_duration']:
            return None
        if not (person['start_min'] <= meet["_start_min"] and meet["_end_min"] <= person['end_min']):
            return None

    # Calculate metrics
    total_meeting_minutes = sum(item["_end_min"] - item["_start_min"] for item in itinerary)
    distinct_friends = len(set(p['name'] for p in seq))
    finish_time = itinerary[-1]["_end_min"]
    # Idle time (waiting time between arrival and meeting start)
    current_loc = start_loc
    current_time = start_time_min
    idle_time = 0
    for i, person in enumerate(seq):
        travel_t = get_travel_time(travel, current_loc, person['location'])
        arrival = current_time + travel_t
        start = itinerary[i]["_start_min"]
        if start > arrival:
            idle_time += start - arrival
        current_loc = person['location']
        current_time = itinerary[i]["_end_min"]

    # Clean itinerary (remove internal mins)
    for item in itinerary:
        item.pop("_start_min", None)
        item.pop("_end_min", None)

    return {
        "itinerary": itinerary,
        "metrics": {
            "friends_met": distinct_friends,
            "total_meeting_minutes": total_meeting_minutes,
            "finish_time": finish_time,
            "idle_time": idle_time
        }
    }

def main():
    # Input variables
    start_location = "The Castro"
    start_time = "9:00"

    travel_times = {
        "The Castro": {
            "Mission District": 7,
            "Financial District": 20
        },
        "Mission District": {
            "The Castro": 7,
            "Financial District": 17
        },
        "Financial District": {
            "The Castro": 23,
            "Mission District": 17
        }
    }

    people = [
        {
            "name": "Laura",
            "location": "Mission District",
            "start": "12:15",
            "end": "19:45",
            "min_duration": 75
        },
        {
            "name": "Anthony",
            "location": "Financial District",
            "start": "12:30",
            "end": "14:45",
            "min_duration": 30
        }
    ]

    # Preprocess
    for p in people:
        p["start_min"] = time_to_minutes(p["start"])
        p["end_min"] = time_to_minutes(p["end"])

    start_time_min = time_to_minutes(start_time)
    name_to_person = {p["name"]: p for p in people}
    friend_names = [p["name"] for p in people]

    # Generate candidate orders (all permutations of all friends, then single-friend options)
    candidate_orders = []
    for r in [len(friend_names), 1]:
        if r == len(friend_names):
            for order in permutations(friend_names, r):
                candidate_orders.append(list(order))
        else:
            for name in friend_names:
                candidate_orders.append([name])

    best = None

    for order in candidate_orders:
        result = evaluate_order(order, start_location, start_time_min, travel_times, name_to_person)
        if result is None:
            continue

        if best is None:
            best = result
        else:
            # Compare based on goals:
            a = result["metrics"]
            b = best["metrics"]

            # 1) Maximize number of friends met
            if a["friends_met"] > b["friends_met"]:
                best = result
                continue
            if a["friends_met"] < b["friends_met"]:
                continue

            # 2) Maximize total meeting minutes
            if a["total_meeting_minutes"] > b["total_meeting_minutes"]:
                best = result
                continue
            if a["total_meeting_minutes"] < b["total_meeting_minutes"]:
                continue

            # 3) Minimize idle time
            if a["idle_time"] < b["idle_time"]:
                best = result
                continue
            if a["idle_time"] > b["idle_time"]:
                continue

            # 4) Earliest finish time
            if a["finish_time"] < b["finish_time"]:
                best = result
                continue

    output = {"itinerary": best["itinerary"] if best else []}
    print(json.dumps(output, ensure_ascii=False))

if __name__ == "__main__":
    main()
